INSERT OR IGNORE INTO courses (id,title,category,level,description,duration_minutes,accent) VALUES
('atomic-architecture','The architecture of an atom','Atomic physics','FOUNDATION','Build a clear picture of the nucleus, orbitals and the forces that make matter stable.',42,'cyan'),
('quantum-states','Quantum states & measurement','Quantum mechanics','INTERMEDIATE','Explore superposition, probability amplitudes and what a measurement changes.',58,'violet'),
('molecular-bonds','How molecules hold together','Chemistry','FOUNDATION','Follow electrons from atomic orbitals into covalent bonds and molecular geometry.',46,'acid'),
('fields-forces','Fields, charge & light','Electromagnetism','INTERMEDIATE','Connect electric fields, magnetic fields and electromagnetic waves.',52,'cyan'),
('particle-zoo','A map of fundamental particles','Particle physics','ADVANCED','Meet quarks, leptons and bosons through the interactions that connect them.',64,'violet'),
('cosmic-elements','Where the elements come from','Cosmology','INTERMEDIATE','Trace the elements from primordial nucleosynthesis to stellar explosions.',49,'acid');

INSERT OR IGNORE INTO lessons (id,course_id,title,summary,body,position,quiz_json) VALUES
('atomic-architecture-01','atomic-architecture','A nucleus with a cloud around it','Separate the compact nucleus from the much larger electron probability cloud.',1,'An atom is mostly open volume. Protons and neutrons occupy a tiny, dense nucleus, while electrons are described by quantum states spread through the surrounding region. The familiar orbit drawing is a useful map, but it is not a miniature solar system.','[{"question":"Where is most of an atom’s mass?","options":["In the electron cloud","In the nucleus","Spread evenly"],"answer":1}]'),
('atomic-architecture-02','atomic-architecture','Charge and the electromagnetic force','Understand why opposite charges attract and like charges repel.',2,'Protons carry positive electric charge and electrons carry negative charge. The electromagnetic interaction binds electrons to nuclei. Neutrons have no net electric charge, though their internal quark structure still participates in the strong interaction.','[{"question":"What holds electrons to an atomic nucleus?","options":["Gravity","Electromagnetism","The strong force"],"answer":1}]'),
('atomic-architecture-03','atomic-architecture','Orbitals are probability maps','Read orbitals as patterns of possible measurement outcomes.',3,'A quantum state predicts the probability of finding an electron in different regions. Orbital shapes come from solutions to the Schrödinger equation for an atom, and each orbital can hold at most two electrons with opposite spin.','[{"question":"An orbital primarily describes…","options":["A fixed electron path","A probability distribution","A proton shell"],"answer":1}]'),
('quantum-states-01','quantum-states','Superposition before measurement','Describe a quantum state as a combination of possible outcomes.',1,'A superposition is a coherent combination of basis states. The amplitudes can interfere, so probabilities depend on both their size and their relative phase. This is different from simply not knowing which classical state is present.','[{"question":"What can relative phase change?","options":["Interference probabilities","The particle’s mass","The detector size"],"answer":0}]'),
('quantum-states-02','quantum-states','Interference as evidence','Connect wave amplitudes to the patterns seen in experiments.',2,'When alternatives remain indistinguishable, their amplitudes add before probabilities are calculated. If the alternatives become distinguishable, interference fades. The two-slit experiment makes this rule visible as a changing pattern of detections.','[{"question":"When do amplitudes add?","options":["Before probabilities, for indistinguishable alternatives","Only after detection","Never"],"answer":0}]'),
('quantum-states-03','quantum-states','What a measurement records','Distinguish an interaction with a detector from a passive look.',3,'A measurement couples a system to a physical apparatus and leaves a record. The outcome is probabilistic, but the probability distribution is constrained by the quantum state and the chosen measurement.','[{"question":"A measurement is best described as…","options":["A detector interaction that records an outcome","A human glance","A particle changing species"],"answer":0}]'),
('molecular-bonds-01','molecular-bonds','Sharing electrons','Explain how a covalent bond forms from shared electron density.',1,'A covalent bond forms when atoms share electron density in a way that lowers the system’s energy. Bonding and antibonding orbitals, nuclear repulsion and electron correlation all contribute to the final structure.','[{"question":"A covalent bond involves…","options":["Shared electron density","Shared neutrons","A magnetic monopole"],"answer":0}]'),
('molecular-bonds-02','molecular-bonds','Shape follows electron pairs','Predict why water is bent while carbon dioxide is linear.',2,'Molecular geometry reflects the arrangement of bonding and lone electron pairs. Water has two O–H bonds and two lone pairs around oxygen, producing a bent shape. Carbon dioxide has two electron domains at carbon and is linear.','[{"question":"What is the shape of water?","options":["Linear","Bent","Tetrahedral"],"answer":1}]'),
('molecular-bonds-03','molecular-bonds','Polarity and attraction','Relate uneven charge distribution to intermolecular forces.',3,'A polar molecule has an uneven distribution of electron density. Partial charges can attract other polar molecules, while temporary fluctuations create dispersion forces present in all atoms and molecules.','[{"question":"Which interaction exists in all atoms?","options":["Dispersion forces","Permanent dipoles only","Covalent bonds between atoms"],"answer":0}]'),
('fields-forces-01','fields-forces','A field is a rule for force','Represent how a charge responds at each point in space.',1,'An electric field assigns a force per unit positive test charge at every location. Field lines are a visualization: their direction follows the force on a positive test charge, and their density indicates field strength.','[{"question":"Electric field is force per…","options":["Unit charge","Unit mass","Unit distance"],"answer":0}]'),
('fields-forces-02','fields-forces','Changing fields make waves','Follow coupled electric and magnetic variations.',2,'A changing electric field is accompanied by a changing magnetic field. Together they can propagate as an electromagnetic wave at the speed of light in vacuum. Radio, visible light and X-rays share this structure.','[{"question":"Visible light is a kind of…","options":["Sound wave","Electromagnetic wave","Matter wave only"],"answer":1}]'),
('fields-forces-03','fields-forces','Energy in a photon','Connect frequency to the energy carried by light.',3,'Photon energy is proportional to frequency: E = h f. Higher-frequency light carries more energy per photon. Intensity instead describes how much energy arrives over an area and time.','[{"question":"If photon frequency rises, its energy…","options":["Rises","Falls","Stays fixed"],"answer":0}]'),
('particle-zoo-01','particle-zoo','Quarks and leptons','Sort the matter particles into two families.',1,'Quarks combine into hadrons such as protons and neutrons. Leptons include electrons and neutrinos. Both families have three generations, though the heavier generations decay rapidly into lighter particles.','[{"question":"Protons are built from…","options":["Quarks","Leptons","Photons"],"answer":0}]'),
('particle-zoo-02','particle-zoo','Bosons carry interactions','Meet photons, gluons and the Higgs boson.',2,'In the Standard Model, gauge bosons mediate interactions: photons for electromagnetism, gluons for the strong force, and W and Z bosons for the weak interaction. The Higgs field is associated with the Higgs boson.','[{"question":"Which particle mediates electromagnetism?","options":["Photon","Gluon","Neutrino"],"answer":0}]'),
('particle-zoo-03','particle-zoo','What the Standard Model leaves open','Separate confirmed theory from unanswered questions.',3,'The Standard Model is a highly successful framework for known elementary particles and three interactions. It does not include gravity as a quantum interaction and does not explain dark matter, neutrino masses in its minimal form, or the matter–antimatter imbalance.','[{"question":"Which interaction is not included in the Standard Model?","options":["Gravity","Electromagnetism","Strong interaction"],"answer":0}]'),
('cosmic-elements-01','cosmic-elements','The first light nuclei','Start with the first minutes of cosmic history.',1,'During Big Bang nucleosynthesis, the hot early universe formed mostly hydrogen and helium nuclei, with small amounts of deuterium, helium-3 and lithium-7. Heavier elements formed later inside stars and stellar explosions.','[{"question":"Which elements dominated after Big Bang nucleosynthesis?","options":["Hydrogen and helium","Iron and gold","Carbon and oxygen"],"answer":0}]'),
('cosmic-elements-02','cosmic-elements','Stars build new nuclei','Follow fusion from hydrogen toward heavier elements.',2,'Stars release energy by fusing light nuclei. Massive stars can build elements up to the iron group through successive burning stages. Beyond iron, many nuclei require energy input or neutron-capture processes.','[{"question":"Ordinary stellar fusion releases energy most readily for…","options":["Light nuclei fusing","Iron splitting","Gold capture"],"answer":0}]'),
('cosmic-elements-03','cosmic-elements','Explosive element factories','Trace neutron capture in stellar events.',3,'Rapid neutron capture, or the r-process, can create many neutron-rich heavy nuclei. Neutron-star mergers are confirmed sites of r-process nucleosynthesis, while the exact contributions of different astrophysical environments continue to be studied.','[{"question":"The r-process is rapid capture of…","options":["Neutrons","Photons","Electrons"],"answer":0}]');

INSERT OR IGNORE INTO articles (id,title,category,excerpt,body,read_minutes,published_at,accent) VALUES
('inside-the-electron-cloud','Inside the electron cloud','Quantum physics','Why an atom is not a miniature solar system.','Electrons occupy quantum states rather than tiny planetary tracks. An orbital maps where an electron is likely to be detected, and the shape of that map follows from the wavefunction.\n\nThe cloud picture is useful because it keeps probability visible. It also reminds us that a measurement yields a localized result even though the state spread across space can predict many possible locations.\n\nFor hydrogen, the orbital solutions can be found exactly. Multi-electron atoms require approximations because the electrons interact with one another. Modern computational chemistry turns those approximations into practical predictions for materials and molecules.',5,'2026-10-28','violet'),
('water-is-a-strange-liquid','The unexpected physics of water','Chemistry','A bent molecule with an outsized influence on climate and life.','Water’s bent geometry and polar O–H bonds create an uneven charge distribution. Nearby molecules form transient hydrogen-bond networks that continually break and reform.\n\nThat network helps explain water’s high heat capacity, surface tension and unusual density maximum near 4 °C. None of those properties belongs to a single isolated molecule; they emerge from many molecules interacting together.\n\nIn cells, oceans and the atmosphere, water is both a solvent and an active participant in chemical and thermal processes.',4,'2026-10-23','cyan'),
('how-starlight-reveals-elements','Reading the elements in starlight','Astrophysics','Spectral lines turn distant light into a chemical fingerprint.','Atoms absorb and emit photons at energies tied to their allowed states. A spectroscope spreads incoming light by wavelength, revealing dark absorption lines or bright emission lines.\n\nBecause each element has its own pattern of transitions, astronomers can infer composition, temperature and motion from spectra. A shift in line position also reveals whether a source is moving toward or away from us.\n\nSpectroscopy connects laboratory measurements to objects far beyond direct reach, from stellar atmospheres to exoplanets.',4,'2026-10-19','acid'),
('the-quantum-vacuum','The quantum vacuum is not empty','Quantum physics','What physicists mean by a vacuum state.','A vacuum is the lowest-energy state of a field, not a box with every field removed. Quantum fields still have measurable correlations, and the vacuum can respond to boundaries, acceleration and strong fields.\n\nThe Casimir effect is one example in which boundary conditions change the forces between conducting surfaces. Its explanation comes from quantum electrodynamics and measurable changes in field modes.\n\nPopular descriptions of particles endlessly popping in and out of existence are metaphors. The more precise account uses field states, correlation functions and observables.',5,'2026-10-14','violet'),
('a-map-of-the-standard-model','A map of the Standard Model','Particle physics','The matter particles and interactions in one compact framework.','The Standard Model organizes quarks, leptons and force-carrying bosons. Its structure predicts a wide range of collider measurements with remarkable precision.\n\nThe framework is not a final theory of everything. It does not quantize gravity, identify dark matter, or explain why the observable universe contains more matter than antimatter. Those gaps guide current experiments and theoretical work.\n\nA useful map includes both what is known and the boundaries where evidence stops.',5,'2026-10-08','cyan'),
('why-iron-matters-to-stars','Why iron marks a turning point in stars','Astrophysics','Fusion gains energy up to iron-group nuclei, then the balance changes.','For many nuclei lighter than the iron group, fusion can release energy because the products are more tightly bound. Fusing nuclei beyond that region generally costs energy.\n\nIn a massive star, an iron-rich core cannot continue the same energy-producing fusion chain. When the core becomes unstable, collapse can trigger a supernova. The explosion then disperses elements made in the star and in the event.\n\nThe exact nucleosynthesis of heavy elements involves several processes and astrophysical sites, including neutron-star mergers.',4,'2026-10-02','acid'),
('magnetic-fields-in-motion','Fields in motion','Electromagnetism','How changing electric and magnetic fields travel together.','Maxwell’s equations link electric and magnetic fields. A changing magnetic field induces an electric field; changing electric fields contribute to magnetic fields.\n\nIn free space these linked changes propagate as electromagnetic waves. Their wavelength and frequency determine whether we call them radio waves, infrared, visible light, ultraviolet, X-rays or gamma rays.\n\nThe same equations describe antennas, optics and signals traveling through interstellar space.',4,'2026-09-26','cyan'),
('molecules-have-shapes','Molecules have shapes','Chemistry','Geometry controls how molecules interact and react.','A molecular structure records the three-dimensional arrangement of nuclei. Bond angles and distances influence polarity, reactivity and the way molecules fit together.\n\nWater is bent, carbon dioxide is linear, and methane is tetrahedral. These shapes are connected to electron density and quantum mechanics, while computational tools help estimate structures too large to solve by hand.\n\nA static diagram is only one view: molecules vibrate, rotate and respond to their surroundings.',3,'2026-09-18','violet');
